def bus(name, loc):
    r = empty(name, loc)
    box(name + '_b', (3.4, 9, 3.6), (0, 0, 2.4), mat('bus_yellow', hexc('#f2b41a'), 0.4), 0.2, parent=r)
    box(name + '_w', (3.5, 7, 1.0), (0, 0, 3.0), mat('bus_win', hexc('#9ad0f0'), 0.2), 0.05, parent=r)
    for i in (-1, 1):
        for j in (-3, 3):
            cyl(name + '_t%d%d' % (i, j), 0.7, 0.5, (i * 1.7, j, 0.7), mat('tire', hexc('#222222'), 0.8), 16, rot=(0, 90, 0), parent=r)
    return r
